import SwiftUI

/// Every number the VCS toolbar uses, in one place.
///
/// The horizontal ones are chosen so the toolbar aligns *by construction* with the section header
/// beneath it rather than by eye: `outerInset` + `glyphSlot` + `glyphSpacing` puts the branch glyph's
/// centre and the branch name's left edge exactly where `SectionHeader`'s chevron centre and title land
/// (`InspectorSplitView.headerLabel` uses the same 12 / 12 / 7).
enum VCSToolbarMetrics {
  /// The tallest thing a text cell stacks: an 11pt semibold title row over a 10pt caption (12pt line),
  /// 1pt apart. The title row is 13pt bare but as tall as a `.caption2` capsule — about 15 — whenever a
  /// count pill rides it, which is the case this has to budget for.
  static let contentHeight: CGFloat = 28
  /// Breathing room above and below a cell's content.
  ///
  /// Expressed as band height rather than as `.padding(.vertical)` on the cells, and that is not a
  /// shortcut: `vcsToolbarSegment` fills its cell with `maxHeight: .infinity`, so the content is
  /// vertically CENTRED in a fixed-height frame. Padding inside a centred fixed frame is absorbed by the
  /// centring and changes nothing on screen — only the band's height actually moves the text off the
  /// hairlines. Anyone adding a `.padding(.vertical)` here to "fix the spacing" will see no difference
  /// and should change this instead.
  static let contentVerticalPadding: CGFloat = 6
  /// 40. Two lines genuinely don't fit the section headers' 34pt, so this must exceed them — being
  /// taller is also what makes the bar read as its own band rather than a fourth section header.
  static let height: CGFloat = contentHeight + contentVerticalPadding * 2
  static let outerInset: CGFloat = 12
  /// Inner edges of the segments — tighter than `outerInset` so the middle segment isn't starved.
  static let innerInset: CGFloat = 8
  /// Matches `SectionHeader`'s chevron `.frame(width: 12)`.
  static let glyphSlot: CGFloat = 12
  /// Matches `SectionHeader`'s `HStack(spacing: 7)`.
  static let glyphSpacing: CGFloat = 7
  /// Between the inspector's 11pt header glyphs and the pane bar's 13pt action icons: it has to hold
  /// against a bold 11pt title without reading as a pane-bar button.
  static let glyph: CGFloat = 12
  /// 22pt well plus 4pt either side — `ToolbarIconButtonStyle.footprint` rounded to a divider-bounded cell.
  static let fetchWidth: CGFloat = 30

  static let titleFont = Font.system(size: 11, weight: .semibold)
  static let captionFont = Font.system(size: 10)
  /// The single-line states. A lone 10pt dim line in the bar reads as a rendering bug, so the solo
  /// subtitle is a step up in both size and contrast.
  static let soloFont = Font.system(size: 11)

  /// ONE floor, shared by the branch and sync segments, because the two are equal width.
  ///
  /// Equal width is what makes the bar read as two halves plus a button rather than three arbitrary
  /// cells, and it's only achievable if both segments have the same floor as well as the same `maxWidth`:
  /// an `HStack` divides slack evenly, so unequal minimums stay unequal by their difference at every
  /// width. The value is set by the narrowest inspector — `2 × 114 + fetchWidth + 2 dividers = 260`,
  /// exactly the 260pt minimum. (It replaces a 100/126 split with a 220 cap on the branch cell; the cap
  /// existed to stop a short name hoarding width, which an even division already does.)
  static let segmentMinWidth: CGFloat = 114

  /// Verbatim from `PRNumberBadge`, so the toolbar's pill matches the ref pill 40pt below it.
  static let pillHorizontalPadding: CGFloat = 5
  static let pillVerticalPadding: CGFloat = 1
  /// The pill's ↑/↓ glyph. Smaller than `glyph` on purpose — it sits inside a `.caption2` capsule and
  /// has to read as a direction marker beside the count, not as an icon in its own right.
  static let pillArrowGlyph: CGFloat = 7
}

/// The VCS toolbar: current branch, a sync segment that shows and performs the right remote action, and
/// a fetch button — divided into three full-height cells.
///
/// Lives at the top of `RightInspector`, above the section stack, and only for the Changes activity
/// section. Deliberately a plain SwiftUI view inside the inspector's content and **never** a `.toolbar`
/// modifier: the window toolbar is kept an empty AppKit `NSToolbar` because a SwiftUI toolbar item's
/// overflow `menuFormRepresentation` caused a multi-second app hang.
struct VCSToolbar: View {
  /// Observed EXPLICITLY, like `HistoryPanel`'s and `FilesPanel`'s models.
  ///
  /// `RemoteStateModel` is its own `ObservableObject`; `AppStore` merely holds it and does not forward
  /// its `objectWillChange`. Reading it through `store.remoteState` alone renders the first state and
  /// then never repaints — clicking Push set `inFlight`, ran the push and recorded the result, and the
  /// toolbar showed none of it. Caught by `VCSToolbarUITests.testClickingPushRequestsAPush`.
  @ObservedObject var model: RemoteStateModel

  @EnvironmentObject var store: AppStore
  /// `ThemeService.shared` isn't observed by SwiftUI, so a theme switch would otherwise leave the
  /// hairlines stale. Same pattern as `ActivityBar`.
  @State private var themeTick = 0

  private var theme: ThemeTokens { ThemeService.shared.tokens }

  /// The toolbar's whole state, resolved in one place so the three segments can't disagree.
  private func presentation(now: Date) -> VCSSyncPresentation {
    VCSSyncPresenter.make(
      state: model.snapshot, hasTarget: model.target != nil,
      toolsUsable: store.vcsAllowsRemoteActions(vcs: model.target?.vcs ?? "git"),
      // `activeAction`, not `inFlight`: the label must describe THIS workroom. `inFlight` is the
      // model-wide lock, so rendering it directly showed "Pushing…" on a workroom that wasn't pushing.
      activity: model.activeAction.map { .running($0) } ?? .idle,
      failure: model.lastFailure, lastAction: model.lastAction,
      pullConflicted: pullConflicted,
      // An action is running, but not for THIS workroom. `perform` would drop the click, so the segment
      // must not look clickable — see `make`'s `busyElsewhere`.
      busyElsewhere: model.inFlight != nil && model.activeAction == nil, now: now)
  }

  /// Whether our own pull left conflicts that are still unresolved.
  ///
  /// The live half is read from the store rather than the model because the model has no view of
  /// working status — `noteConflictState` is pushed into it once, after the sweep that follows a pull,
  /// and is never revised. Reading `workroomStatuses` here means resolving the conflicts in a terminal
  /// clears the message on the next sweep, instead of it lingering until the next action.
  private var pullConflicted: Bool {
    guard let sid = model.target?.sid else { return false }
    return VCSSyncPresenter.pullConflicted(
      lastPullConflicted: model.lastPullConflicted,
      statusConflicted: store.workroomStatuses[sid]?.conflicted == true)
  }

  var body: some View {
    // Only the relative timestamp needs to tick, so `TimelineView` wraps the whole bar but the schedule
    // is coarse (30s) and every other value is already `@Published`. Confining it to just the timestamp
    // `Text` would need the presentation recomputed per-subview, which is worse.
    TimelineView(.periodic(from: .now, by: 30)) { context in
      let p = presentation(now: context.date)
      HStack(spacing: 0) {
        // The branch and sync cells are EQUAL width: same floor, same `maxWidth: .infinity`, and no
        // `layoutPriority` on either. All three parts are load-bearing — an `HStack` splits slack evenly
        // only between views that are equally flexible, so a priority override or a different floor
        // reintroduces the imbalance. (An earlier version gave sync `layoutPriority(1)` AND
        // `maxWidth: .infinity`, so it was offered the whole width first and claimed it, pinning the
        // branch cell at its floor even in a wide inspector: `feature/login` rendered as `fe…gin`.)
        VCSBranchSegment(name: branchName, vcs: model.target?.vcs)
          .frame(minWidth: VCSToolbarMetrics.segmentMinWidth, maxWidth: .infinity)
        divider
        VCSSyncSegment(presentation: p, onAct: { perform(p.action) })
          .frame(minWidth: VCSToolbarMetrics.segmentMinWidth, maxWidth: .infinity)
        divider
        VCSFetchSegment(
          isRunning: model.activeAction == .fetch,
          isEnabled: model.canFetch
            && store.vcsAllowsRemoteActions(vcs: model.target?.vcs ?? "git"),
          onFetch: { perform(.fetch) }
        )
        .frame(width: VCSToolbarMetrics.fetchWidth)
      }
      .frame(height: VCSToolbarMetrics.height)
      .frame(maxWidth: .infinity)
      .overlay(alignment: .bottom) { theme.border.frame(height: 1) }
      .accessibilityElement(children: .contain)
      .accessibilityIdentifier("vcs.toolbar")
    }
    .id(themeTick)
    .onReceive(NotificationCenter.default.publisher(for: .themeDidChange)) { _ in themeTick += 1 }
  }

  /// Full-bleed, unlike `TitlebarDivider` (a 14pt inline group rule) — it's what makes the three cells
  /// read as segments rather than as a row of controls.
  private var divider: some View {
    Rectangle().fill(theme.border).frame(width: 1).frame(maxHeight: .infinity)
  }

  /// Read through the one accessor every branch-showing surface uses, so this can't disagree with the
  /// status bar or the sidebar.
  private var branchName: String? {
    model.target.flatMap { store.branchName(for: $0.sid) }
  }

  /// Hands straight to the store, which owns the dirty-tree confirmation gate.
  ///
  /// The gate used to live here, and that was the bug: the Source Control menu calls
  /// `performRemoteAction` directly, so ⌥⇧⌘P autostashed a dirty tree with no warning while this button
  /// warned. A gate only one of two entry points honours isn't a gate.
  private func perform(_ action: VCSRemoteAction?) {
    guard let action else { return }
    store.performRemoteAction(action)
  }
}

/// Segment 1: the current branch. **Display only — not a control.**
///
/// Not a dropdown, and not a button either. Workrooms **are** branches — a workroom's identity is its
/// directory name, with no branch field anywhere in the config — so switching a workroom's branch would
/// make its name permanently wrong, and the jj equivalent (`jj new <bookmark>`) was reproduced removing
/// a file from the working copy and orphaning the workroom's commit. With switching gone there is no
/// action left that belongs on the branch name, so this is a label: no `Button`, no hover well, no
/// chevron. Each of those would promise something that doesn't happen.
///
/// It still carries a `.help` — middle truncation hides the middle of a long name, and the tooltip is
/// how you read the whole thing — plus a right-click "Copy Branch Name". Neither is a click action.
private struct VCSBranchSegment: View {
  let name: String?
  /// The target's backend (`"git"` / `"jj"`), nil when nothing is selected. Every string in this segment
  /// derives from it through `VCSSyncPresenter`, so the caption, the tooltip and the spoken label can't
  /// drift out of agreement — and the mapping stays unit-testable rather than inline here.
  let vcs: String?

  private var noun: String { VCSSyncPresenter.refNoun(vcs: vcs) }
  private var caption: String { VCSSyncPresenter.refCaption(vcs: vcs) }
  private var theme: ThemeTokens { ThemeService.shared.tokens }

  var body: some View {
    HStack(spacing: VCSToolbarMetrics.glyphSpacing) {
      Image(systemName: "arrow.triangle.branch")
        .font(.system(size: VCSToolbarMetrics.glyph))
        .foregroundStyle(theme.fgMuted)
        .frame(width: VCSToolbarMetrics.glyphSlot)
      // The caption is unconditional. It used to sit in a `ViewThatFits` ladder against a name-only
      // variant, which dropped it far more often than intended and in the wrong circumstances:
      // `ViewThatFits` measures each variant's IDEAL width, and a `.lineLimit(1)` truncating `Text`
      // reports its FULL untruncated string as its ideal — so the caption was vetoed by a long *name*,
      // never by a narrow cell. jj repos lost it almost always (bookmark names, or the ancestor bookmark
      // a workspace's unbookmarked `@` resolves to, run longer than a `feature/login`) while git repos
      // kept it, which is exactly the asymmetry that got reported. The name truncates instead; at the
      // 114pt floor the caption truncates too, which is honest degradation rather than a silent drop.
      VStack(alignment: .leading, spacing: 1) {
        Text(caption)
          .font(VCSToolbarMetrics.captionFont)
          .foregroundStyle(theme.fgDim)
          .lineLimit(1)
          .truncationMode(.tail)
        nameText
      }
      Spacer(minLength: 0)
    }
    .padding(.leading, VCSToolbarMetrics.outerInset)
    .padding(.trailing, VCSToolbarMetrics.innerInset)
    // The cell's own layout, WITHOUT `vcsToolbarSegment`'s hover fill: that treatment marks a segment as
    // clickable, and this one isn't. `contentShape` is still needed so the tooltip and context menu have
    // the full cell as their hit region rather than just the glyph and text glyphs.
    .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .leading)
    .contentShape(Rectangle())
    .help(name ?? "No \(noun) resolved yet")
    // A `Button` was implicitly ONE accessibility element; a plain `HStack` is not, so without this its
    // caption and name would be exposed as two unrelated strings.
    .accessibilityElement(children: .ignore)
    // Caption AND name in the LABEL, not split across label + value.
    //
    // `.accessibilityValue` does not survive on this element: once it stopped being a `Button` and got
    // collapsed with `children: .ignore`, AppKit maps it to a static-text element whose value the
    // modifier no longer sets — it read back as the empty string, which failed both tests that assert the
    // name. (`ChangesPanel`'s combined header shows the mirror-image of the same mapping: there the
    // children's text lands in the VALUE and the label comes back empty.) The label is the one field that
    // reliably carries what we set, so both parts go in it — and VoiceOver reads it as one phrase, which
    // is what a two-line label is anyway.
    .accessibilityLabel("\(caption): \(name ?? "unknown")")
    .accessibilityIdentifier("vcs.toolbar.branch")
    .contextMenu {
      // Offered as a menu item rather than making the label selectable: `.textSelection(.enabled)`
      // swallows real mouseDown, which would stop this segment being clickable with an actual mouse
      // while synthetic test clicks kept passing.
      if let name {
        Button("Copy \(noun.capitalized) Name") {
          NSPasteboard.general.clearContents()
          NSPasteboard.general.setString(name, forType: .string)
        }
      }
    }
  }

  /// `.middle` truncation, because a long branch's distinguishing part is usually its tail
  /// (`joel/history-refs-pill`) — the same reasoning the Changes header and status bar already follow.
  private var nameText: some View {
    Text(name ?? "—")
      .font(VCSToolbarMetrics.titleFont)
      .lineLimit(1)
      .truncationMode(.middle)
  }
}

/// Segment 2: what to do about the remote, and doing it.
///
/// Line order is inverted relative to segment 1 — bold title over dim subtitle — which is what the
/// reference design specifies. The consequence is that the two segments' bold lines do **not** share a
/// baseline: both blocks are the same height and vertically centred, so a caption-first block sits low and a
/// title-first block sits high. The full-height divider between them is what makes that read as two
/// groups rather than a misalignment. Called out because it looks like a bug and isn't.
private struct VCSSyncSegment: View {
  let presentation: VCSSyncPresentation
  let onAct: () -> Void

  @State private var hovering = false
  @Environment(\.accessibilityReduceMotion) private var reduceMotion
  private var theme: ThemeTokens { ThemeService.shared.tokens }

  private var toneColor: Color {
    switch presentation.tone {
    case .normal: return theme.fgDim
    case .warning: return theme.warning
    case .failure: return theme.failure
    }
  }

  var body: some View {
    Button(action: onAct) {
      HStack(spacing: VCSToolbarMetrics.glyphSpacing) {
        if let symbol = presentation.symbol {
          Image(systemName: symbol)
            .font(.system(size: VCSToolbarMetrics.glyph))
            .foregroundStyle(presentation.tone == .normal ? theme.fgMuted : toneColor)
            .frame(width: VCSToolbarMetrics.glyphSlot)
        } else if presentation.action != nil, isRunning {
          ProgressView().controlSize(.mini).frame(width: VCSToolbarMetrics.glyphSlot)
        }
        content
      }
      .padding(.horizontal, VCSToolbarMetrics.innerInset)
      .vcsToolbarSegment(hovering: hovering && presentation.isEnabled, reduceMotion: reduceMotion)
    }
    .buttonStyle(.plain)
    .disabled(!presentation.isEnabled)
    // Deliberately NO disabled dim, unlike `ToolbarIconButtonStyle`. Every disabled state here is a
    // MESSAGE, not a withheld action — "No remote configured", "No repository", "Pushing…", and the
    // `.failure`-toned retry line — so all of them have to stay readable; the suppressed hover well is
    // what says "not clickable". An `.opacity(0.4)` here also COMPOUNDS: the text is already
    // `fgMuted` (fg @ 0.65), so it landed at an effective 0.26, fainter than `fgDim` (0.40) — the
    // placeholder tier — and dimmed error copy along with it. That convention's 0.4 is right only
    // because it sits on full-strength `fg`.
    .onHover { hovering = $0 }
    .help(presentation.help)
    .accessibilityLabel(presentation.accessibility)
    .accessibilityValue(presentation.accessibilityValue)
    .accessibilityIdentifier("vcs.toolbar.sync")
    // Only when a lock file is blocking the repo. Workroom deliberately doesn't delete it — telling a
    // live git's lock from an abandoned one isn't possible from outside the process, and deleting a live
    // one corrupts the index — so the fix is the user's to make, and these hand them the file rather
    // than making them retype a path out of a tooltip.
    .contextMenu {
      if let lockPath = presentation.lockPath {
        Button("Copy Lock File Path") {
          NSPasteboard.general.clearContents()
          NSPasteboard.general.setString(lockPath, forType: .string)
        }
        Button("Reveal Lock File in Finder") {
          NSWorkspace.shared.activateFileViewerSelecting([URL(fileURLWithPath: lockPath)])
        }
      }
    }
  }

  private var isRunning: Bool { presentation.title?.hasSuffix("…") == true }

  @ViewBuilder private var content: some View {
    if presentation.isSingleLine {
      HStack(spacing: VCSToolbarMetrics.glyphSpacing) {
        // Centred and a step up in size/contrast: a lone dim 10pt line in the bar reads as broken.
        Text(presentation.subtitle)
          .font(VCSToolbarMetrics.soloFont)
          .foregroundStyle(presentation.tone == .normal ? theme.fgMuted : toneColor)
          .lineLimit(1)
          .truncationMode(.tail)
        Spacer(minLength: 4)
        pills
      }
    } else {
      VStack(alignment: .leading, spacing: 1) {
        // The pills ride the TITLE line rather than the whole cell. As siblings of this VStack they
        // narrowed BOTH lines, and the line they cost the most was the one that could least afford it:
        // the timestamp is the longest string in the bar ("Fetched 22 minutes ago") and the only one
        // whose full form is worth reading, while the title above it is short and has an abbreviation
        // ladder to fall back on. Now the timestamp gets the segment's whole width and the pills
        // compete only with the title, which is what the ladder is for.
        HStack(spacing: VCSToolbarMetrics.glyphSpacing) {
          // Longest variant first — `ViewThatFits` takes the first that fits, so inverting this order
          // silently defeats the whole ladder. `VCSSyncPresentationTests` pins the ordering.
          ViewThatFits(in: .horizontal) {
            ForEach(presentation.titleVariants, id: \.self) { variant in
              Text(variant).font(VCSToolbarMetrics.titleFont).lineLimit(1)
            }
          }
          Spacer(minLength: 4)
          pills
        }
        // The staleness caveat abbreviates but survives. It must NOT be the first thing dropped: the
        // count pill it qualifies is pinned, so losing the caveat first would leave an unverified number
        // standing alone.
        ViewThatFits(in: .horizontal) {
          Text(presentation.subtitle)
          Text(presentation.subtitleShort)
        }
        .font(VCSToolbarMetrics.captionFont)
        .foregroundStyle(toneColor)
        .lineLimit(1)
        .truncationMode(.tail)
      }
      // The cell no longer has a `Spacer` of its own to fill it, so the VStack claims the width — which
      // is also what lets the subtitle's ladder measure against the full cell.
      .frame(maxWidth: .infinity, alignment: .leading)
    }
  }

  /// Ahead first, then behind — the diverged order the presenter fixes (`↓` before `↑` is decided there,
  /// not here; this just renders `badge` then `secondaryBadge`).
  @ViewBuilder private var pills: some View {
    if let badge = presentation.badge { VCSCountPill(badge: badge) }
    if let secondary = presentation.secondaryBadge { VCSCountPill(badge: secondary) }
  }
}

/// Segment 3: fetch.
///
/// `arrow.down.circle`, not `arrow.clockwise`: the Changes header's Refresh button is already
/// `arrow.clockwise` roughly 40pt below and 10pt to the left, and two near-identical circular-arrow
/// glyphs meaning different things (re-read local status vs contact the remote) is a real confusion.
/// The down-arrow also matches the ↓ direction language of the count pills.
private struct VCSFetchSegment: View {
  let isRunning: Bool
  let isEnabled: Bool
  let onFetch: () -> Void

  @State private var hovering = false
  @Environment(\.accessibilityReduceMotion) private var reduceMotion
  private var theme: ThemeTokens { ThemeService.shared.tokens }

  var body: some View {
    Button(action: onFetch) {
      Group {
        if isRunning {
          // `.mini`, not `.small`: small is ~16pt and would overflow the 12pt glyph slot.
          ProgressView().controlSize(.mini)
        } else {
          Image(systemName: "arrow.down.circle")
            .font(.system(size: VCSToolbarMetrics.glyph))
            // Unlike segment 2 this IS a bare affordance, so unavailable should read as unavailable —
            // but as ONE tier, not a multiply. `fgDim` is fg @ 0.40, the same effective alpha
            // `ToolbarIconButtonStyle`'s `.opacity(0.4)` produces on its full-strength glyphs.
            .foregroundStyle(isEnabled ? theme.fgMuted : theme.fgDim)
        }
      }
      .frame(maxWidth: .infinity)
      .vcsToolbarSegment(hovering: hovering && isEnabled, reduceMotion: reduceMotion)
    }
    .buttonStyle(.plain)
    .disabled(!isEnabled || isRunning)
    .onHover { hovering = $0 }
    .help(isRunning ? "Fetching…" : "Fetch from the remote")
    .accessibilityLabel("Fetch")
    .accessibilityIdentifier("vcs.toolbar.fetch")
  }
}

/// A count pill: `5 ↑` / `3 ↓`.
///
/// Geometry and font copied from `PRNumberBadge` so it matches the ref pill in the Changes header just
/// below. Both directions use the same `surface` fill rather than hue-coding: the arrow carries the
/// direction (shape, not colour) and a count is a quantity, not a severity.
private struct VCSCountPill: View {
  let badge: VCSSyncPresentation.Badge
  private var theme: ThemeTokens { ThemeService.shared.tokens }

  var body: some View {
    HStack(spacing: 2) {
      Text("\(badge.count)").font(.caption2).fontWeight(.semibold).monospacedDigit()
      Image(systemName: badge.direction == .ahead ? "arrow.up" : "arrow.down")
        .font(.system(size: VCSToolbarMetrics.pillArrowGlyph, weight: .semibold))
    }
    .foregroundStyle(theme.fgMuted)
    .padding(.horizontal, VCSToolbarMetrics.pillHorizontalPadding)
    .padding(.vertical, VCSToolbarMetrics.pillVerticalPadding)
    .background(Capsule().fill(theme.surface))
    // The highest-information 30pt in the bar — it must never yield.
    .fixedSize()
    // The spoken form comes from the sync button's `accessibilityValue`; a pill read separately would
    // just be a bare number with no subject.
    .accessibilityHidden(true)
  }
}

extension View {
  /// One hover treatment for all three segments: the whole divider-bounded cell fills.
  ///
  /// Deliberately not the 22pt inset well `InspectorHeaderButton` uses — that's right for a control
  /// floating in a header row, but inside a cell whose bounds are drawn by hairlines a small inner well
  /// reads as a mistake. Opacity is animated, never the view tree: an implicit tree animation
  /// interpolates a glyph's 1pt pixel re-round into a visible slide (see `ToolbarIconButtonStyle`).
  fileprivate func vcsToolbarSegment(hovering: Bool, reduceMotion: Bool) -> some View {
    self
      .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .leading)
      .background(
        ThemeService.shared.tokens.hover
          .opacity(hovering ? 1 : 0)
          .animation(reduceMotion ? nil : .easeOut(duration: 0.12), value: hovering)
      )
      .contentShape(Rectangle())
  }
}

import Foundation

/// What the VCS toolbar's middle segment is currently doing.
enum VCSSyncActivity: Equatable, Sendable {
  case idle
  case running(VCSRemoteAction)
}

/// Everything the toolbar's sync segment renders, resolved from one state snapshot.
///
/// A pure mapping, kept out of the view for the same reason as `ChangeBadge`: it's a many-case
/// decision that silently drifts. `now` is a parameter rather than a `Date()` read so the whole thing
/// is testable at fixed instants.
struct VCSSyncPresentation: Equatable, Sendable {
  /// Title variants, LONGEST FIRST, for a `ViewThatFits` ladder. Empty ⇒ single-line mode: the segment
  /// renders only `subtitle`, vertically centred, at a larger weight.
  var titleVariants: [String] = []
  var subtitle: String
  /// A shorter subtitle for narrow widths. The staleness caveat abbreviates but must never be the
  /// first thing dropped — the unverified count it qualifies is the thing that should yield.
  var subtitleShort: String
  var symbol: String?
  var badge: Badge?
  var secondaryBadge: Badge?
  var action: VCSRemoteAction?
  var isEnabled: Bool
  var tone: Tone = .normal
  var help: String
  /// Spoken label. The count pills are `accessibilityHidden`, so their information has to arrive here.
  var accessibility: String
  var accessibilityValue: String = ""
  /// The blocking lock file, when there is one. Carried so the segment can offer to copy or reveal it —
  /// the fix is a file operation the user performs, so the least Workroom can do is hand them the path
  /// rather than make them transcribe it out of a tooltip.
  var lockPath: String?

  struct Badge: Equatable, Sendable {
    enum Direction: Equatable, Sendable { case ahead, behind }
    let count: Int
    let direction: Direction
  }

  enum Tone: Equatable, Sendable { case normal, warning, failure }

  var title: String? { titleVariants.first }
  var isSingleLine: Bool { titleVariants.isEmpty }
}

/// Maps a `VCSRemoteState` to what the sync segment shows.
///

  /// **Exhaustive on purpose — no `default:`.** It used to end `default: return lastAction`, so every
  /// failure added later silently inherited "offer a retry", which is the exact defect the `[13]` tier
  /// exists to prevent. Two of the failures below were added precisely because they are permanent, and a
  /// `default:` would have handed them a doomed button without a compile error.
  static func retryAction(for failure: VCSRemoteFailure, lastAction: VCSRemoteAction?)
    -> VCSRemoteAction?
  {
    switch failure {
    case .rebaseInProgress: return .abortRebase
    case .rejected: return .pull  // the fix for a rejection is to pull, never to force
    case .toolMissing, .noRemote: return nil
    // Permanent until the user does something outside Workroom: describe the commit, or move off a base
    // whose history is protected. Retrying either runs the identical command and fails identically.
    case .needsDescription, .immutableHistory: return nil
    case .timedOut, .authRequired, .hostKeyUnverified, .dirtyWorkingTree, .other:
      return lastAction
    // A LOCATED lock file offers nothing, for `rebaseInProgress`'s reason: the file is sitting there, so
    // every retry fails identically and the button is a promise that can't be kept. Removing it is the
    // only fix and Workroom won't do that for you (see `VCSRemoteFailure.locked`), so the recovery is
    // explained rather than offered. An unlocatable lock was transient contention — retry away.
    case .locked(let file): return file == nil ? lastAction : nil
    }
  }

  /// Whether the pull **we** ran has conflicts still outstanding — the `[14]` tier's condition.
  ///
  /// Both halves are load-bearing. `lastPullConflicted` says the conflicts came from Workroom's own
  /// pull: a workroom can be conflicted from a merge the user ran in a terminal, and attributing that to
  /// the Pull button would be a lie. The live status says they are still there: the flag is cleared only
  /// by a new action or a workroom switch, so on its own the message would outlive the conflicts and go
  /// on calling a resolved tree broken.
  static func pullConflicted(lastPullConflicted: Bool, statusConflicted: Bool) -> Bool {
    lastPullConflicted && statusConflicted
  }

  /// One-line, actionable copy per failure. The raw stderr is legible for some cases and baffling for
  /// others, so the baffling ones get written copy.
  static func describe(_ failure: VCSRemoteFailure) -> String {
    switch failure {
    case .toolMissing(let tool):
      return "\(tool) isn’t on Workroom’s PATH."
    case .timedOut(let action):
      return "\(action.label) timed out."
    case .authRequired:
      // The #1 expected failure. The runner sets GIT_TERMINAL_PROMPT=0 and ssh BatchMode, so this
      // fails instantly rather than hanging — but the raw stderr is baffling, hence bespoke copy.
      return "Couldn’t authenticate. Load your key into ssh-agent, or set a credential helper."
    case .hostKeyUnverified:
      return "The host’s key isn’t known. Connect once from a terminal to accept it."
    case .noRemote:
      return "No remote configured."
    case .rejected:
      return "Rejected — the remote has commits you don’t. Pull first."
    case .dirtyWorkingTree:
      return "Uncommitted changes are in the way. Commit or stash them first."
    case .rebaseInProgress:
      return "A rebase is in progress. Abort it to continue."
    case .locked(let file):
      // Two different facts, so two different sentences. Saying "busy, try again" over a lock file that
      // is still there sends the user round a loop that cannot terminate.
      guard let file else { return "The repository was busy. Try again." }
      return "A leftover \(file.filename) is blocking git."
    case .needsDescription:
      // The most reachable failure on the push path: this is every workroom between the first edit and
      // the first commit message. The remedy is one command, so name it.
      return "Describe the change before pushing it (jj describe)."
    case .immutableHistory:
      return "Pull would rewrite shared history here, so it can’t run."
    case .other(let message):
      return message.split(whereSeparator: \.isNewline).first.map(String.init) ?? "Failed."
    }
  }

  /// The blocking lock file's path, when the failure has one.
  static func lockPath(of failure: VCSRemoteFailure) -> String? {
    guard case .locked(let file) = failure else { return nil }
    return file?.path
  }

  /// The tooltip form of a failure: `describe`'s one-liner plus, where there is one, the remedy.
  ///
  /// Only `.locked` currently says more than its subtitle, because it's the only failure whose fix is a
  /// thing the user must do OUTSIDE Workroom — and the app deliberately won't do it for them, so the
  /// message has to be complete enough to act on: which file, how old, and the caveat that makes the age
  /// worth printing. A minutes-old lock with no git running is abandoned; a seconds-old one probably
  /// isn't, and that judgement is the user's to make.
  static func explain(_ failure: VCSRemoteFailure, now: Date) -> String {
    guard case .locked(let file) = failure, let file else { return describe(failure) }
    let age = fullFormatter.localizedString(for: file.modifiedAt, relativeTo: now)
    return """
      A leftover lock file is blocking git.

      \(file.path)
      Created \(age).

      A git command that was force-stopped leaves this behind. If no git command is running for this \
      repository, deleting the file is safe:

      rm "\(file.path)"
      """
  }

  // MARK: Vocabulary

  /// What this backend calls the thing the working copy is on: jj says **bookmark**, git says **branch**.
  ///
  /// Not cosmetic. A jj bookmark does NOT advance as you commit, which is the defining behaviour of a git
  /// branch — so calling it a branch in a jj repo teaches the wrong model of the tool the user is running.
  ///
  /// A pure function rather than a ternary inside the view because that's the only way it can be tested:
  /// the toolbar's caption is not reachable from a unit test, and driving a real jj project through the
  /// GUI needs both a selected row and an open terminal.
  ///
  /// Anything that isn't `"jj"` — including an empty or unrecognised value — reads as "branch". `vcs` comes
  /// from the CLI config, so git is the safe default for an unknown, and it matches every non-jj repo the
  /// app can currently open.
  static func refNoun(vcs: String?) -> String { vcs == "jj" ? "bookmark" : "branch" }

  /// The branch segment's caption: "Current Branch" / "Current Bookmark".
  static func refCaption(vcs: String?) -> String { "Current \(refNoun(vcs: vcs).capitalized)" }

  // MARK: Relative time

  private static let fullFormatter: RelativeDateTimeFormatter = {
    let f = RelativeDateTimeFormatter()
    f.unitsStyle = .full
    return f
  }()

  private static let shortFormatter: RelativeDateTimeFormatter = {
    let f = RelativeDateTimeFormatter()
    f.unitsStyle = .abbreviated
    return f
  }()

  /// "Fetched 9 minutes ago" / "Fetched 9 min. ago" / "Never fetched" / "".
  ///
  /// Both forms say "Fetched", never "Last fetched": "ago" already places it in the past, so "Last" only
  /// spent width. `short` differs by the formatter's unit style alone.
  ///
  /// Under a minute reads "just now" rather than "in 0 seconds", which is what
  /// `RelativeDateTimeFormatter` produces for a sub-second delta.
  ///
  /// `.unknown` renders NOTHING — never the word "never". They are different facts: `.never` means we
  /// looked and there was no fetch; `.unknown` means we couldn't tell.
  static func fetchedAgo(_ lastFetch: VCSLastFetch, now: Date, short: Bool = false) -> String {
    switch lastFetch {
    case .never: return "Never fetched"
    case .unknown: return ""
    case .at(let date):
      if now.timeIntervalSince(date) < 60 { return "Fetched just now" }
      let formatter = short ? shortFormatter : fullFormatter
      return "Fetched \(formatter.localizedString(for: date, relativeTo: now))"
    }
  }
}

import Defaults
import Foundation

/// Store-owned state for the VCS toolbar: the selected workroom's branch, its divergence from the
/// remote, when the project last fetched, and the fetch/push/pull actions.
///
/// Modelled on `HistoryModel` — same `State`/`isSettled`, the same **pre-dispatch** trailing debounce,
/// cancel-and-replace, and the same injected-resolver seam. The debounce reasoning transfers verbatim:
/// arrow-key cycling the sidebar re-points this model per row, and each read spawns processes.
@MainActor
final class RemoteStateModel: ObservableObject {
  enum State: Equatable {
    case idle
    case loading
    case loaded
    case failed(String)

    var isSettled: Bool {
      switch self {
      case .loaded, .failed: return true
      case .idle, .loading: return false
      }
    }
  }

  /// What the model is pointed at. Carries `projectRoot` because fetch always runs there, and `vcs`
  /// because the tool floor is scoped per backend.
  struct Target: Equatable, Sendable {
    let sid: SidebarID
    let path: String
    let vcs: String
    let projectRoot: String
  }

  @Published private(set) var state: State = .idle
  @Published private(set) var snapshot: VCSRemoteState?
  /// The single in-flight action, or nil. Drives the spinner on the acting segment AND disables all of
  /// them, so a second click can't double-fire and Push can't race Pull.
  @Published private(set) var inFlight: VCSRemoteAction?
  /// The last action failure. Kept SEPARATE from `state` so a failed push never blanks a good snapshot
  /// — the `keepPrior` rule the CI/PR resolvers already follow. Cleared on the next action or refresh.
  @Published private(set) var lastFailure: VCSRemoteFailure?
  /// Which action produced `lastFailure`, so the segment can offer the right retry.
  @Published private(set) var lastAction: VCSRemoteAction?
  /// Set when a pull succeeded but left conflicts. jj records conflicts INSIDE commits and its rebase
  /// exits 0, so the exit code can't tell — this is raised by `noteConflictState` from the status
  /// refresh that follows a mutation, i.e. after the gate has released (re-reading inside it would
  /// deadlock the project's queue).
  @Published private(set) var lastPullConflicted = false

  private(set) var target: Target?
  private let makeWriter: @Sendable (URL) throws -> VCSWriting
  private let debounce: TimeInterval
  private let ttl: TimeInterval
  /// Minimum gap between automatic fetches for one project. An automatic fetch is a network call the
  /// user didn't ask for, so it must be rare enough to be unremarkable.
  private let autoFetchInterval: TimeInterval
  private let now: @Sendable () -> Date
  private var task: Task<Void, Never>?
  private var actionTask: Task<Void, Never>?
  /// Which workroom the in-flight action belongs to.
  ///
  /// `inFlight` is a model-WIDE lock — one action at a time, because the writer and `JJSnapshotGate` are
  /// shared — but the toolbar renders per selection, so "an action is running" and "an action is running
  /// *here*" are different questions. Without this, switching workrooms mid-push left the newly selected
  /// one showing "Pushing…" with every segment disabled until the other workroom's action finished (up to
  /// 300s for a pull).
  private var inFlightTarget: Target?
  /// When each project last auto-fetched, in-memory (a relaunch may legitimately fetch again).
  private var lastAutoFetch: [String: Date] = [:]

  /// Fired after a successful mutation so the store can refresh everything downstream — workroom
  /// status (the dirty/conflict badge), the commit history, and this model itself. Wired post-init so
  /// the model needs no `AppStore` to be unit-tested (the `workroomFileWatcher` idiom).
  var onDidMutate: (@MainActor (VCSRemoteAction, SidebarID) -> Void)?
  /// Publishes the resolved branch name so `AppStore.branchName(for:)` — the one accessor every
  /// branch-showing surface reads — can lead with it. This model is the only writer.
  var onBranchResolved: (@MainActor (SidebarID, String?) -> Void)?

  init(
    makeWriter: @escaping @Sendable (URL) throws -> VCSWriting = { try VCS.writer(for: $0) },
    debounce: TimeInterval = 0.3, ttl: TimeInterval = 15,
    autoFetchInterval: TimeInterval = 300,
    now: @escaping @Sendable () -> Date = Date.init
  ) {
    self.makeWriter = makeWriter
    self.debounce = debounce
    self.ttl = ttl
    self.autoFetchInterval = autoFetchInterval
    self.now = now
  }

  // MARK: Focus

  /// Point the model at a workroom (or clear it with `nil`). No-op if already there.
  func focus(_ target: Target?) {
    guard self.target != target else { return }
    self.target = target
    snapshot = nil
    lastFailure = nil
    lastPullConflicted = false
    guard target != nil else {
      task?.cancel()
      state = .idle
      return
    }
    load()
  }

  /// The panel's `.task`: on a genuine re-entry (same target, a load already settled) pull fresh;
  /// otherwise defer to `focus`. The `isSettled` guard prevents a redundant second read when the store
  /// just called `focus` eagerly, and retries after a transient failure.
  func activate(_ target: Target?) {
    if self.target == target, target != nil, state.isSettled {
      refresh()
    } else {
      focus(target)
    }
  }

  /// Re-read. TTL-gated unless `force` — a watcher can fire several times for one logical change.
  func refresh(force: Bool = false) {
    guard target != nil else { return }
    if !force, let resolvedAt = snapshot?.resolvedAt, now().timeIntervalSince(resolvedAt) < ttl {
      return
    }
    load()
  }

  /// Await whatever is in flight.
  ///
  /// Order matters: an action schedules a refresh when it finishes, so the action must be awaited
  /// FIRST and the load task re-read afterwards. Awaiting `task` first captures the pre-action load and
  /// returns before the refresh the action queued has even been created.
  func awaitCurrentLoad() async {
    await actionTask?.value
    await task?.value
  }

  private func load() {
    guard let target else { return }
    task?.cancel()
    state = .loading
    let makeWriter = self.makeWriter
    let debounce = self.debounce
    task = Task { [weak self] in
      if debounce > 0 {
        try? await Task.sleep(nanoseconds: UInt64(debounce * 1_000_000_000))
        if Task.isCancelled { return }
      }
      let root = URL(fileURLWithPath: target.path, isDirectory: true)
      let resolution: VCSRemoteResolution
      do {
        resolution = await (try makeWriter(root)).remoteState(
          path: target.path, projectRoot: target.projectRoot)
      } catch {
        resolution = .absent
      }
      if Task.isCancelled { return }
      self?.apply(resolution, for: target)
    }
  }

  private func apply(_ resolution: VCSRemoteResolution, for target: Target) {
    // A read that finished after the model moved on must not overwrite the new target's state.
    guard self.target == target else { return }
    switch resolution {
    case .state(let state):
      // Merge in Workroom's own fetch record. Needed because jj's fetch is invisible: it passes
      // `--no-write-fetch-head`, and a fetch that brings nothing records NO operation at all — so the
      // op-log scan alone would mean "last fetch that changed something", and clicking Fetch with
      // nothing new would leave a stale timestamp on screen. The backend still wins when it is newer,
      // which keeps a fetch run in the user's own terminal visible.
      snapshot = Self.merging(state, ownFetch: Defaults[.vcsLastFetch][target.projectRoot])
      self.state = .loaded
      onBranchResolved?(target.sid, state.current.name)
    case .absent:
      snapshot = nil
      self.state = .loaded
      onBranchResolved?(target.sid, nil)
    case .keepPrior:
      // A transient blip — leave the last good snapshot standing rather than blanking the toolbar.
      self.state = snapshot == nil ? .idle : .loaded
    case .failed(let failure):
      snapshot = nil
      self.state = .failed(VCSSyncPresenter.describe(failure))
      onBranchResolved?(target.sid, nil)
    }
  }

  /// Take the later of the backend's own evidence and Workroom's recorded fetch.
  static func merging(_ state: VCSRemoteState, ownFetch: Date?) -> VCSRemoteState {
    guard let ownFetch else { return state }
    let merged: VCSLastFetch
    switch state.lastFetch {
    case .at(let backend): merged = .at(max(backend, ownFetch))
    case .never, .unknown: merged = .at(ownFetch)
    }
    return VCSRemoteState(
      current: state.current, tracking: state.tracking, remotes: state.remotes,
      primaryRemote: state.primaryRemote, lastFetch: merged, resolvedAt: state.resolvedAt)
  }

  // MARK: Derived

  /// The in-flight action IF it belongs to the workroom currently on screen — what the toolbar renders.
  ///
  /// Distinct from `inFlight`, which is the model-wide lock and is what `canFetch`/`canPush`/`canPull`
  /// gate on: a second action must be blocked even when it was started from another workroom, because
  /// the writer and the gate are shared. Only the LABEL is per-target.
  var activeAction: VCSRemoteAction? { inFlightTarget == target ? inFlight : nil }

  var canFetch: Bool { snapshot?.primaryRemote != nil && inFlight == nil }
  var canPush: Bool { snapshot?.primaryRemote != nil && inFlight == nil }
  /// Pull needs something to pull FROM: a counterpart that exists on the remote.
  var canPull: Bool {
    guard snapshot?.primaryRemote != nil, inFlight == nil else { return false }
    guard let tracking = snapshot?.tracking else { return false }
    return !tracking.gone
  }

  func canPerform(_ action: VCSRemoteAction) -> Bool {
    switch action {
    case .fetch: return canFetch
    case .push: return canPush
    case .pull: return canPull
    case .abortRebase: return inFlight == nil
    }
  }

  // MARK: Actions

  /// Perform an action. Dropped if one is already in flight — the model is deliberately single-action
  /// so a double-click can't fire twice and Push can't race Pull.
  ///
  /// `anonymousRevision` matters only for a jj workroom whose `@` carries no bookmark: pushing a bare
  /// `@` fails when the working copy is empty and undescribed, which is exactly the state a fresh
  /// workroom sits in. Callers pass `CLIVCSWriter.jjPushRevision(hasChanges:hasDescription:)`.
  func perform(
    _ action: VCSRemoteAction, setUpstream: Bool = false, anonymousRevision: String = "@"
  ) {
    guard inFlight == nil, let target, let snapshot else { return }
    // Aborting a rebase is purely local — requiring a remote would leave a workroom wedged in a rebase
    // with no way out from the UI, which is the one state where recovery matters most.
    let remote = snapshot.primaryRemote ?? ""
    if remote.isEmpty, action != .abortRebase {
      lastFailure = .noRemote
      lastAction = action
      return
    }
    inFlight = action
    inFlightTarget = target
    lastAction = action
    lastFailure = nil
    lastPullConflicted = false
    let makeWriter = self.makeWriter
    let current = snapshot.current
    let tracking = snapshot.tracking
    actionTask = Task { [weak self] in
      let root = URL(fileURLWithPath: target.path, isDirectory: true)
      let result: VCSRemoteActionResult
      do {
        let writer = try makeWriter(root)
        switch action {
        case .fetch:
          result = await writer.fetch(
            path: target.path, projectRoot: target.projectRoot, remote: remote)
        case .push:
          result = await writer.push(
            path: target.path, projectRoot: target.projectRoot, current: current, remote: remote,
            setUpstream: setUpstream, anonymousRevision: anonymousRevision)
        case .pull:
          result = await writer.pullRebase(
            path: target.path, projectRoot: target.projectRoot, current: current, remote: remote,
            tracking: tracking)
        case .abortRebase:
          result = await writer.abortRebase(path: target.path, projectRoot: target.projectRoot)
        }
      } catch {
        result = .failed(.other("\(error)"))
      }
      self?.finish(action, result: result, for: target)
    }
  }

  private func finish(_ action: VCSRemoteAction, result: VCSRemoteActionResult, for target: Target)
  {
    // Always cleared: the action really is over, and this is the model-wide single-action lock. What is
    // NOT unconditional is the RESULT, below.
    inFlight = nil
    inFlightTarget = nil
    // The work happened in `target`'s repo whatever is selected now, so the fetch stamp and the
    // downstream refresh belong to it and fire regardless.
    if case .ok = result {
      if action == .fetch || action == .pull { recordOwnFetch(projectRoot: target.projectRoot) }
      onDidMutate?(action, target.sid)
    }
    // Everything past here writes PUBLISHED state that the toolbar renders for whatever is selected NOW,
    // so it needs the same guard `apply` has. Without it, starting a push in one workroom and switching
    // to another put the first one's failure — and its action label — on the second one's toolbar,
    // reporting a failure for a workroom where nothing was attempted.
    guard self.target == target else { return }
    switch result {
    case .ok:
      lastFailure = nil
      // Re-read immediately AND let the store refresh everything downstream. The metadata watcher
      // would get there on its own, but its coalesce window is ~1s and the toolbar should feel instant.
      refresh(force: true)
    case .failed(let failure):
      // Deliberately leaves `snapshot` intact: a failed action tells you nothing new about the repo.
      lastFailure = failure
    }
  }

  /// Stamp Workroom's own fetch time for this project. See `merging` for why this exists.
  private func recordOwnFetch(projectRoot: String) {
    var stamps = Defaults[.vcsLastFetch]
    stamps[projectRoot] = now()
    Defaults[.vcsLastFetch] = stamps
  }

  /// Called by the store after the post-mutation status refresh lands: a pull that reported success may
  /// still have produced conflicts (jj writes them into commits and exits 0).
  /// `sid` is the workroom the pull ran in — checked, not trusted, for the same reason `finish` checks it:
  /// the sweep this waits on is async, so the selection can move before it lands.
  func noteConflictState(_ conflicted: Bool, for sid: SidebarID) {
    guard target?.sid == sid, lastAction == .pull, lastFailure == nil else { return }
    lastPullConflicted = conflicted
  }

  // MARK: Auto-fetch

  /// Fetch when the inspector gains focus, at most once per `autoFetchInterval` per project.
  ///
  /// Automatic, so it must be quiet: a failure sets `lastFailure` for the tooltip but raises no alert
  /// and never blocks the read path. Callers gate on the inspector being visible with the Changes
  /// section active, so a hidden toolbar never triggers a network call.
  func autoFetchIfDue() {
    guard let target, inFlight == nil, let snapshot, snapshot.primaryRemote != nil else { return }
    if let last = lastAutoFetch[target.projectRoot],
      now().timeIntervalSince(last) < autoFetchInterval
    {
      return
    }
    lastAutoFetch[target.projectRoot] = now()
    perform(.fetch)
  }
}

