1	import AppKit
2	import Defaults
3	import SwiftUI
4	
5	/// The right inspector (issue #24). macOS 14 supports only one `.inspector` per view, so the
6	/// inspector composes four collapsible sections — **Changes** (the selected workroom's VCS detail),
7	/// **History** (its commit log), **Files** (the repo tree), and **Pull Request** — rather than
8	/// separate inspectors. The toolbar `sidebar.right` toggle shows/hides the whole inspector; each
9	/// section's disclosure handles its own visibility (persisted). (Notifications moved to the left
10	/// sidebar, issue #118.)
11	struct RightInspector: View {
12	  @EnvironmentObject var store: AppStore
13	  @EnvironmentObject var notifications: NotificationCenterStore
14	  @Environment(\.openURL) private var openURL
15	  /// A PR action awaiting confirmation (close), surfaced via a confirmation dialog.
16	  @State private var pendingConfirm: PendingPRAction?
17	
18	  var body: some View {
19	    // The active activity-bar section decides which sub-sections this pane stacks (Changes stacks
20	    // Changes + History + Pull Request; Files is solo). Each sub-section's header + body are handed
21	    // to the NSSplitView bridge (see InspectorSplitView) as environment-injected AnyViews — the tree
22	    // does NOT inherit our `@EnvironmentObject`s across NSHostingController. Collapse flags +
23	    // size-weights persist as full `InspectorSectionKind.allCases`-ordered vectors on the store; we
24	    // slice out — and write back — the entries for the sub-sections actually shown, by `storeIndex`.
25	    let subs = store.activeInspectorSection.subSections
26	    VStack(spacing: 0) {
27	      // The VCS toolbar sits ABOVE the section stack, not inside a section, so it survives a collapsed
28	      // Changes section. Only for the Changes activity section: branch/remote state is what that section
29	      // is about, and showing it over the Files tree would jump the layout on every activity-bar click.
30	      if store.activeInspectorSection == .changes {
31	        VCSToolbar(model: store.remoteState)
32	      }
33	      inspectorSplit(subs: subs)
34	    }
35	    // Bound to the STORE, not a local `@State`: the gate that raises this lives in
36	    // `AppStore.performRemoteAction` so the Source Control menu's ⌥⇧⌘P goes through it too. When the
37	    // toolbar owned the gate, the shortcut autostashed a dirty tree with no warning at all.
38	    .confirmationDialog(
39	      store.pendingRemoteConfirm.map { "\($0.action.label) with uncommitted changes?" } ?? "",
40	      isPresented: Binding(
41	        get: { store.pendingRemoteConfirm != nil },
42	        set: { if !$0 { store.pendingRemoteConfirm = nil } }),
43	      presenting: store.pendingRemoteConfirm
44	    ) { item in
45	      // `runRemoteAction(on:)`, which re-checks `item.sid` — the dialog isn't modal to the sidebar, so
46	      // the selection can move while it's open and `performRemoteAction` would re-derive the target.
47	      Button(item.action.label) { store.runRemoteAction(item.action, on: item.sid) }
48	      Button("Cancel", role: .cancel) {}
49	    } message: { _ in
50	      Text("Your uncommitted changes will be stashed and reapplied after the rebase.")
51	    }
52	  }
53	
54	  @ViewBuilder private func inspectorSplit(subs: [InspectorSectionKind]) -> some View {
55	    InspectorSplitView(
56	      headers: subs.map { sectionHeader(for: $0) },
57	      bodies: subs.map { sectionBody(for: $0) },
58	      collapsed: subs.map { collapsedValue(for: $0) },
59	      // History hosts its body in fill mode (it scrolls itself via SwiftUI) so its divergence
60	      // expander animates cleanly; the other sections keep the default NSScrollView hosting.
61	      fills: subs.map { $0 == .history },
62	      sectionKey: store.activeInspectorSection.rawValue,
63	      // The section layout is GLOBAL, not per-workroom, so this key is constant: switching workrooms
64	      // must not trigger the controller's workroom-switch redistribute (only a section change, via
65	      // `sectionKey`, or a genuine collapse/drag re-lays out the panes).
66	      workroomKey: "global",
67	      weights: subs.map { store.inspectorSizeWeights[$0.storeIndex] },
68	      onWeightsChanged: { shown in
69	        var full = store.inspectorSizeWeights
70	        for (index, sub) in subs.enumerated() where index < shown.count {
71	          full[sub.storeIndex] = shown[index]
72	        }
73	        store.updateInspectorSizeWeights(full)
74	      }
75	    )
76	    .frame(minWidth: 260, maxWidth: .infinity, maxHeight: .infinity, alignment: .top)
77	    .confirmationDialog(
78	      pendingConfirm.map { "\($0.action.label)?" } ?? "",
79	      isPresented: Binding(
80	        get: { pendingConfirm != nil }, set: { if !$0 { pendingConfirm = nil } }),
81	      presenting: pendingConfirm
82	    ) { item in
83	      Button(item.action.label, role: .destructive) {
84	        store.performPRAction(item.action, number: item.number, on: item.sid)
85	      }
86	      Button("Cancel", role: .cancel) {}
87	    }
88	  }
89	
90	  /// The live collapse value for a sub-section. A solo pane (Files, which stacks only itself) never
91	  /// collapses, so it reports expanded and its header shows no chevron.
92	  private func collapsedValue(for sub: InspectorSectionKind) -> Bool {
93	    switch sub {
94	    case .changes: return store.changesSectionCollapsed
95	    case .files: return false
96	    case .pullRequest: return store.prSectionCollapsed
97	    case .history: return store.historySectionCollapsed
98	    }
99	  }
100	
101	  /// A sub-section's sticky header, environment-injected for the NSHostingController-hosted tree.
102	  /// Files passes a nil collapse binding (solo pane → no chevron).
103	  private func sectionHeader(for sub: InspectorSectionKind) -> AnyView {
104	    switch sub {
105	    case .changes:
106	      return AnyView(
107	        SectionHeader(
108	          title: "Changes", collapsed: $store.changesSectionCollapsed,
109	          indicator: changesIndicator, indicatorLabel: changesIndicatorLabel, shortcut: "⌥⌘C"
110	        ) {
111	          InspectorHeaderButton(systemImage: "arrow.clockwise", help: "Refresh workroom status") {
112	            store.refreshWorkroomStatuses(force: true)
113	          }
114	        }
115	        .environmentObject(store).environmentObject(notifications))
116	    case .files:
117	      return AnyView(
118	        SectionHeader(title: "Files", collapsed: nil, shortcut: "⌥⌘F") {
119	          InspectorHeaderButton(systemImage: "arrow.clockwise", help: "Refresh files") {
120	            store.fileTree.reload()
121	          }
122	        }
123	        .environmentObject(store).environmentObject(notifications))
124	    case .pullRequest:
125	      return AnyView(
126	        SectionHeader(title: "Pull Request", collapsed: $store.prSectionCollapsed, shortcut: "⌥⌘P")
127	        {
128	          prHeaderAccessory
129	        }
130	        .environmentObject(store).environmentObject(notifications))
131	    case .history:
132	      return AnyView(
133	        SectionHeader(
134	          title: "History", collapsed: $store.historySectionCollapsed, shortcut: "⌥⌘Y"
135	        ) {
136	          // Disabled while collapsed: a collapsed section deliberately stops tracking the selection
137	          // (`historySectionShown` gates the re-point), so the model still points at whatever workroom
138	          // was selected when it shut — clicking Refresh there would read THAT repo's log, not the
139	          // selected one, for a list nobody can see. Expanding re-points first, then loads.
140	          InspectorHeaderButton(
141	            systemImage: "arrow.clockwise", help: "Refresh history",
142	            disabled: store.historySectionCollapsed
143	          ) {
144	            store.commitHistory.refresh()
145	          }
146	        }
147	        .environmentObject(store).environmentObject(notifications))
148	    }
149	  }
150	
151	  /// A sub-section's scrollable body, environment-injected for the hosted tree.
152	  private func sectionBody(for sub: InspectorSectionKind) -> AnyView {
153	    switch sub {
154	    case .changes:
155	      return AnyView(ChangesPanel().environmentObject(store).environmentObject(notifications))
156	    case .files:
157	      return AnyView(
158	        FilesPanel(model: store.fileTree).environmentObject(store).environmentObject(notifications))
159	    case .pullRequest:
160	      return AnyView(PullRequestPanel().environmentObject(store).environmentObject(notifications))
161	    case .history:
162	      return AnyView(
163	        HistoryPanel(model: store.commitHistory).environmentObject(store).environmentObject(
164	          notifications))
165	    }
166	  }
167	
168	  /// The Pull Request header's trailing controls (issue #77): the PR number badge — a link to the
169	  /// PR, tinted by state and turning red when checks fail — then the actions menu. The draft-only
170	  /// "Ready for Review" button moved into the panel body (above the title) so it can't crowd the
171	  /// section title in a narrow inspector (issue #93 feedback). Order is left → right, so the ellipsis
172	  /// stays rightmost (matching the other section headers).
173	  @ViewBuilder private var prHeaderAccessory: some View {
174	    HStack(spacing: 6) {
175	      prNumberLink
176	      prActionsMenu
177	    }
178	  }
179	
180	  /// The PR number badge, now a link that opens the PR in the browser (issue #77) — it replaces the
181	  /// in-panel status row's open-in-browser affordance, so the header always carries the link. Tinted
182	  /// by PR state (open/draft/merged/closed), but red when the PR's checks are failing.
183	  @ViewBuilder private var prNumberLink: some View {
184	    if store.githubCLIStatus == .available, let status = selectedStatus, let pr = status.pr {
185	      let badge = PRPresentation.badge(pr)
186	      // Failing checks only recolor an *open* PR — a merged (purple) / closed (red) badge shouldn't
187	      // be repainted by stale check history.
188	      let failing = pr.state == .open && PRPresentation.isFailing(status)
189	      let tint: Color = failing ? .red : badge.semantic.color
190	      let failSuffix = failing ? ", checks failing" : ""
191	      PRNumberBadge(
192	        number: pr.number, tint: tint, url: URL(string: pr.url),
193	        help: "Pull request #\(String(pr.number)): \(badge.label)\(failSuffix). Open in browser.",
194	        accessibility:
195	          "Pull request #\(String(pr.number)), \(badge.label)\(failSuffix), open in browser")
196	    }
197	  }
198	
199	  /// The PR header menu: "Go to Pull Request" (always available when there's a PR), plus the
200	  /// state-dependent write actions (ready/draft, close, reopen — Phase 2b; destructive ones route
201	  /// through a confirmation dialog). Shown whenever there's a PR, so a merged/closed PR with no
202	  /// remaining actions can still be opened in the browser.
203	  @ViewBuilder private var prActionsMenu: some View {
204	    if store.githubCLIStatus == .available, let pr = selectedStatus?.pr,
205	      let sid = store.selectedTargetID
206	    {
207	      let actions = PRAction.available(for: pr)
208	      Menu {
209	        Button {
210	          if let url = URL(string: pr.url) { openURL(url) }
211	        } label: {
212	          Label("Go to Pull Request", systemImage: "arrow.up.right.square")
213	        }
214	        if !actions.isEmpty {
215	          Divider()
216	          ForEach(actions, id: \.self) { action in
217	            Button(role: action.isDestructive ? .destructive : nil) {
218	              if action.needsConfirmation {
219	                pendingConfirm = PendingPRAction(action: action, number: pr.number, sid: sid)
220	              } else {
221	                store.performPRAction(action, number: pr.number, on: sid)
222	              }
223	            } label: {
224	              Label(action.label, systemImage: action.systemImage)
225	            }
226	          }
227	        }
228	      } label: {
229	        Image(systemName: "ellipsis").font(.system(size: 11)).foregroundStyle(.secondary)
230	      }
231	      // `.menuStyle(.button)` (NOT `.borderlessButton`) renders the trigger as a SwiftUI button, so
232	      // `InspectorMenuButtonStyle` can give it the same rounded hover fill + comfortable click
233	      // target as the other header buttons. A `.borderlessButton` menu is AppKit-backed and never
234	      // reports hover. Clicking still drops the native menu — consistent with the rest of the app.
235	      .menuStyle(.button)
236	      .buttonStyle(InspectorMenuButtonStyle())
237	      .menuIndicator(.hidden)
238	      .fixedSize()
239	      .disabled(store.prActionInFlight)
240	      .help("Pull request actions")
241	      .accessibilityLabel("Pull request actions")
242	    }
243	  }
244	
245	  /// A 1px rule between sections so adjacent (especially collapsed) header bars stay separated.
246	  private var sectionRule: some View {
247	    ThemeService.shared.tokens.border.frame(height: 1)
248	  }
249	
250	  /// The selected workroom's status, or nil when a non-target (project) or nothing is selected —
251	  /// drives the header indicators so a collapsed section still shows state.
252	  private var selectedStatus: WorkroomStatus? {
253	    guard let sid = store.inspectorTargetID else { return nil }
254	    if case .project = sid { return nil }
255	    return store.workroomStatuses[sid]
256	  }
257	
258	  /// Changes header indicator: how many files changed (a capsule count) and the working-tree line counts
259	  /// (`+N` green / `-M` red) when there's a delta. Nothing at all if clean.
260	  ///
261	  /// The file count is deliberately NOT inside the line-counts branch. `lineCountsHelp` is nil for an
262	  /// untracked-only dirty tree, which is exactly a case where files changed and no `+/−` can be
263	  /// computed — the count is the only thing there is to say, so it has to render on its own.
264	  ///
265	  /// **The dirty dot is gone; the unknown one is not.** `VCSStatusPresentation.dot` answers three
266	  /// different questions, and the count only replaces one of them. Its `.dirty` circle said "this tree
267	  /// has changes", which is now the capsule beside it saying so with a number; its conflict triangle is
268	  /// already rendered here in its own right. But its `questionmark.circle` says the probe FAILED —
269	  /// timed out, busy, not a repository — and a failed probe reports no files and no line counts, so
270	  /// dropping it wholesale would render "status unavailable" identically to "clean". That case keeps its
271	  /// glyph, and with it the specific reason in the tooltip.
272	  private var changesIndicator: AnyView {
273	    guard let s = selectedStatus else { return AnyView(EmptyView()) }
274	    let ins = s.insertions ?? 0
275	    let del = s.deletions ?? 0
276	    // `changedFiles` mirrors `jjWorkingCopy?.files` for jj (both come from the one summary probe), so
277	    // this is the same number for both backends and matches the rows rendered below.
278	    let files = s.changedFiles?.count ?? 0
279	    let countsHelp = VCSStatusPresentation.lineCountsHelp(s)
280	    // `!s.conflicted` because `dot` checks conflict FIRST and would hand back the triangle this row
281	    // already draws — a status that is both conflicted and unreadable would otherwise show two.
282	    let dot = s.isUnknown && !s.conflicted ? VCSStatusPresentation.dot(s) : nil
283	    if files == 0, countsHelp == nil, dot == nil { return AnyView(EmptyView()) }
284	    return AnyView(
285	      HStack(spacing: 5) {
286	        if s.conflicted {
287	          Image(systemName: "exclamationmark.triangle.fill")
288	            .font(.system(size: 9)).foregroundStyle(Color.red)
289	        }
290	        if files > 0 { ChangedFileCountBadge(count: files) }
291	        if let countsHelp {
292	          HStack(spacing: 5) {
293	            if ins > 0 { Text("+\(ins)").foregroundStyle(.green) }
294	            if del > 0 { Text("-\(del)").foregroundStyle(.red) }
295	          }
296	          .help(countsHelp)
297	        }
298	        if let dot {
299	          Image(systemName: dot.symbol).font(.system(size: 9)).foregroundStyle(dot.semantic.color)
300	            .help(dot.accessibility)
301	        }
302	      }
303	      .font(.caption).monospacedDigit())
304	  }
305	
306	  // VoiceOver text for each header indicator (the visual badge can't be read through the collapse
307	  // button's own label), appended to the section's accessibility label.
308	
309	  private var changesIndicatorLabel: String {
310	    guard let s = selectedStatus else { return "" }
311	    // The capsule count is a `Text` inside the combined header element, so it never reaches the
312	    // accessibility tree on its own — it has to be spoken here or not at all.
313	    // `> 0` so this tracks the badge exactly — a clean tree renders no capsule and must speak none.
314	    let files = (s.changedFiles?.count).flatMap {
315	      $0 > 0 ? ChangedFileCountBadge.phrase(count: $0) : nil
316	    }
317	    // Mirrors what the row now draws: line counts, or the unavailable reason, and no longer "working
318	    // tree has changes" — the count phrase above already says that, in files rather than in prose.
319	    let detail =
320	      VCSStatusPresentation.lineCountsHelp(s)
321	      ?? (s.isUnknown ? VCSStatusPresentation.dot(s)?.accessibility : nil)
322	    return [files, detail].compactMap { $0 }.joined(separator: ", ")
323	  }
324	}
325	
326	/// A PR action awaiting user confirmation (the close action), carried by the confirmation dialog.
327	private struct PendingPRAction: Identifiable {
328	  let action: PRAction
329	  let number: Int
330	  let sid: SidebarID
331	  var id: String { "\(action.rawValue)-\(number)" }
332	}
333	
334	/// The Changes section header's changed-file count.
335	///
336	/// Geometry and type are `PRNumberBadge`'s, so the two section headers' badges match — but this one is
337	/// not a `Button` and takes no hover: it's a quantity, not a link. The neutral `.quaternary` fill is the
338	/// same capsule the ref chips in the body use, deliberately not a tinted one — the severity signal in
339	/// this header is the conflict glyph and the `+/−` colours beside it, and a coloured count would compete
340	/// with them for the same meaning.
341	private struct ChangedFileCountBadge: View {
342	  let count: Int
343	
344	  /// Also spoken by the section's accessibility label, which is why it's a static rather than inline.
345	  static func phrase(count: Int) -> String {
346	    count == 1 ? "1 changed file" : "\(count) changed files"
347	  }
348	
349	  var body: some View {
350	    // `verbatim:` for the same reason `PRNumberBadge` uses it — no LocalizedStringKey digit grouping.
351	    Text(verbatim: "\(count)")
352	      .font(.caption2).fontWeight(.semibold).monospacedDigit()
353	      .foregroundStyle(.secondary)
354	      .padding(.horizontal, 5).padding(.vertical, 1)
355	      .background(.quaternary, in: Capsule())
356	      .help(Self.phrase(count: count))
357	  }
358	}
359	
360	/// The Pull Request section header's number badge (issue #77): a capsule "#N" link that opens the PR
361	/// in the browser, tinted by PR state (red when checks fail). A standalone view so it can carry its
362	/// own `@State` hover, which the `@ViewBuilder` accessory can't — the capsule fill deepens on hover.
363	private struct PRNumberBadge: View {
364	  let number: Int
365	  let tint: Color
366	  let url: URL?
367	  let help: String
368	  let accessibility: String
369	  @Environment(\.openURL) private var openURL
370	  @State private var hovering = false
371	
372	  var body: some View {
373	    Button {
374	      if let url { openURL(url) }
375	    } label: {
376	      // `verbatim:` so the Int isn't run through LocalizedStringKey number formatting, which would
377	      // group it as "#1,042" — a PR number is an identifier, not a quantity.
378	      Text(verbatim: "#\(number)")
379	        .font(.caption2).fontWeight(.semibold).monospacedDigit()
380	        .foregroundStyle(tint)
381	        .padding(.horizontal, 5).padding(.vertical, 1)
382	        .background(Capsule().fill(tint.opacity(hovering ? 0.34 : 0.22)))
383	        .contentShape(Capsule())
384	    }
385	    .buttonStyle(.plain)
386	    .onHover { hovering = $0 }
387	    .help(help)
388	    .accessibilityLabel(accessibility)
389	  }
390	}
391	
392	/// One changed-file row: a colored change-kind letter (M/A/D/…), the filename, then its parent
393	/// directory dimmed (issue #24 feedback). Clicking opens the file's diff in the workroom's tab strip
394	/// (issue #66): a single click opens it in preview mode (eagerly — the diff appears at once), a quick
395	/// double-click persists it. `source` is the row's group (git worktree / jj `@` / jj `@-`), so the
396	/// diff resolves against the right revision. The directory yields first when space is tight
397	/// (truncates from the head). The change kind is spelled out in the accessibility label.
398	private struct ChangedFileRow: View {
399	  let file: ChangedFile
400	  /// Which revision this row's diff comes from — the Changes group it's rendered under.
401	  let source: DiffSource
402	  @EnvironmentObject var store: AppStore
403	  /// Observed so the row's selected state tracks which diff tab is focused (the tab strip lives in
404	  /// a separate observation tree from the inspector).
405	  @ObservedObject var sessions: TerminalSessions
406	  @State private var hovering = false
407	  /// Time of the last click, so a quick second click promotes the preview tab to persisted (eager
408	  /// single/double discrimination — the single click never waits).
409	  @State private var lastClick: Date?
410	  /// Observed so the hover toolbar / context-menu "Open file in <editor>" label updates live when
411	  /// the user changes Settings → "Open file paths in" (issue #93); otherwise it'd be stale until an
412	  /// unrelated redraw.
413	  @Default(.filePathEditor) private var filePathEditorID
414	  private let theme = ThemeService.shared
415	
416	  var body: some View {
417	    let (dir, name) = ChangesPanel.splitPath(file.path)
418	    // Baseline-aligned, not centered: the path is a smaller face than the filename, so centering
419	    // would float it off the name's baseline.
420	    HStack(alignment: .firstTextBaseline, spacing: 6) {
421	      Text(letter)
422	        .font(.system(.callout, design: .monospaced))
423	        .foregroundStyle(color)
424	        .frame(width: 14, alignment: .leading)
425	      Text(name)
426	        .font(.callout)
427	        .foregroundStyle(isSelected ? theme.tokens.accent : .primary)
428	        .lineLimit(1).truncationMode(.middle)
429	        .layoutPriority(1)
430	      if !dir.isEmpty {
431	        // Same face as the History detail file list's path line (`ChangesetDetailView.fileRow`):
432	        // caption, monospaced, `.tertiary`. Matching the tint matters — the two panels sit one tab
433	        // apart, and `.secondary` beside `.tertiary` reads as two different kinds of text rather
434	        // than the same one.
435	        //
436	        // Truncation is the one thing that deliberately differs. History stacks the full path UNDER
437	        // the name and truncates it in the middle; here the directory sits INLINE before a
438	        // `layoutPriority(1)` name, where the tail (the directory the file is actually in) is the
439	        // part that identifies it — so it truncates from the head. Middle-truncation on a one-line
440	        // inline dir would clip both ends and leave the least useful segment.
441	        Text(dir)
442	          .font(.system(.caption, design: .monospaced))
443	          .foregroundStyle(.tertiary)
444	          .lineLimit(1).truncationMode(.head)
445	      }
446	      Spacer(minLength: 0)
447	    }
448	    .padding(.vertical, 4)
449	    .padding(.horizontal, 6)
450	    .frame(maxWidth: .infinity, alignment: .leading)
451	    .background(
452	      // Square, full-width band (no corner radius): bleed past the section's 12pt inset so the
453	      // hover/selection highlight fills the inspector width edge-to-edge (issue #93 feedback).
454	      Rectangle()
455	        .fill(isSelected ? theme.tokens.rowSelection : (hovering ? theme.tokens.rowHover : .clear))
456	        .padding(.horizontal, -12)
457	    )
458	    // The row's tooltip describes its click action (open the diff). Applied BEFORE the hover overlay
459	    // so it scopes to the row content only — the trailing "Open file" button, painted on top, keeps
460	    // its OWN tooltip. A `.help` applied after the overlay covers the whole row and occludes the
461	    // button's, so hovering the button wrongly showed "Open diff for …" (issue #117 follow-up).
462	    // A moved file's old path has nowhere to go in this single-line row, so the tooltip carries it
463	    // (`old → new`); the wider changeset detail list shows it inline.
464	    .help(file.oldPath == nil ? "Open diff" : "Open diff — \(renamePath)")
465	    // Hover toolbar (issue #93): a content-sized cluster pinned to the trailing edge, painted over
466	    // the path. Only the button area intercepts clicks (it opens the file) — the rest of the row
467	    // still opens the diff. Built only while hovering, so the editor-name lookup runs on hover only.
468	    .overlay(alignment: .trailing) { if hovering { rowToolbar } }
469	    .contentShape(Rectangle())
470	    .onHover { hovering = $0 }
471	    .onTapGesture {
472	      if NSEvent.modifierFlags.contains(.command) {
473	        store.openChangedFileInEditor(file)  // ⌘-click → open the file, not the diff (issue #93)
474	        lastClick = nil  // clear any pending double-click state so the next plain click is fresh
475	        return
476	      }
477	      let now = Date()
478	      if let last = lastClick, now.timeIntervalSince(last) < 0.35 {
479	        store.openDiffPersistent(file, source: source)  // quick second click → persist
480	        lastClick = nil
481	      } else {
482	        store.openDiffPreview(file, source: source)  // eager: open the preview immediately
483	        lastClick = now
484	      }
485	    }
486	    .accessibilityElement(children: .ignore)
487	    .accessibilityAddTraits(isSelected ? [.isButton, .isSelected] : .isButton)
488	    .accessibilityIdentifier("changes.file.\(file.path)")
489	    .accessibilityLabel(
490	      accessibilityLabel(name: name, dir: dir)
491	    )
492	    // A non-pointer path to the open-file actions (the hover toolbar is mouse-only): keyboard /
493	    // VoiceOver reach them here. "Open File" opens the in-app viewer (issue #117); "Open File in …"
494	    // keeps the external-editor path (issue #93). Both no-op for a deleted file (no working copy).
495	    .contextMenu {
496	      Button {
497	        store.openChangedFileInApp(file)
498	      } label: {
499	        Label("Open File", systemImage: "doc.text")
500	      }
501	      .disabled(file.change == .deleted)
502	      Button {
503	        store.openChangedFileInEditor(file)
504	      } label: {
505	        Label("Open File in \(openFileEditorName)", systemImage: "arrow.up.forward.app")
506	      }
507	      .disabled(file.change == .deleted)
508	    }
509	  }
510	
511	  /// The trailing hover toolbar: the in-app "Open File" button (extensible to more buttons; issue
512	  /// #117). Hidden for a deleted file — there's no working copy to open — so the toolbar renders
513	  /// nothing. Its backing is the same opaque `rowHover`/`rowSelection` token the row uses for its
514	  /// highlight, so the toolbar is solid (occludes the path text) and exactly the same colour as the row.
515	  @ViewBuilder private var rowToolbar: some View {
516	    if file.change != .deleted {
517	      HStack(spacing: 2) {
518	        TabToolbarButton(
519	          systemImage: "doc.text", help: "Open file",
520	          accessibilityLabel: "Open file",
521	          identifier: "changes.file.openFile.\(file.path)"
522	        ) {
523	          store.openChangedFileInApp(file)
524	        }
525	      }
526	      .padding(.horizontal, 2)
527	      .background(
528	        // The same opaque token the row fills its highlight with — solid (occludes the path text) and
529	        // identical in colour to the row by construction.
530	        RoundedRectangle(cornerRadius: 5)
531	          .fill(isSelected ? theme.tokens.rowSelection : theme.tokens.rowHover)
532	      )
533	      .fixedSize()
534	    }
535	  }
536	
537	  /// Display name of the editor the "Open file in…" action targets — the Settings "Open file paths
538	  /// in" choice (`ExternalEditor.forFilePaths`), or "your default app" when unset. Recomputes when
539	  /// `filePathEditorID` changes (issue #93).
540	  private var openFileEditorName: String {
541	    ExternalEditor.forFilePaths?.name ?? "your default app"
542	  }
543	
544	  /// True when the selected target's focused content tab is this row — either its diff (opened by a
545	  /// row click) or its file (opened by the in-app "Open File", issue #117) — so the row that's
546	  /// showing in the pane reads as selected. The file match ignores `source` since a file tab has no
547	  /// revision; the diff match keeps it so the same path under `@` vs `@-` selects the right row.
548	  private var isSelected: Bool {
549	    guard let target = store.selectedTarget, let tab = sessions.focusedTab(for: target)
550	    else { return false }
551	    switch tab.content {
552	    case .diff(let descriptor): return descriptor.path == file.path && descriptor.source == source
553	    case .file(let descriptor): return descriptor.path == file.path
554	    default: return false
555	    }
556	  }
557	
558	  // Letter / colour / word live in `ChangeBadge` (Core) so the mapping is unit-testable — see its
559	  // doc for why `.conflicted` is `"!"` in its own colour rather than `"C"` in deletion's red.
560	  private var letter: String { ChangeBadge.letter(file.change) }
561	  private var color: Color { ChangeBadge.color(file.change, theme.tokens) }
562	  private var changeWord: String { ChangeBadge.word(file.change) }
563	  /// `old → new`, for the tooltip and accessibility label of a moved file.
564	  private var renamePath: String {
565	    ChangeBadge.pathLine(path: file.path, oldPath: file.oldPath)
566	  }
567	
568	  /// The row's spoken label. A moved file says where it came from — VoiceOver has no tooltip to fall
569	  /// back on, and the row only shows the new path.
570	  private func accessibilityLabel(name: String, dir: String) -> String {
571	    let place = dir.isEmpty ? "" : ", in \(dir)"
572	    let from = file.oldPath.map { ", from \($0)" } ?? ""
573	    return "\(name), \(changeWord)\(place)\(from), open diff"
574	  }
575	}
576	
577	/// Applies `accessibilityElement(children: .combine)` + an identifier only when `identifier` is
578	/// non-nil, so the jj Changes header becomes one queryable a11y element (the panel's render sentinel,
579	/// `changes.workingCopy`) while the git header — which no UI test waits on — stays untouched.
580	private struct CombinedA11y: ViewModifier {
581	  let identifier: String?
582	  func body(content: Content) -> some View {
583	    if let identifier {
584	      content.accessibilityElement(children: .combine).accessibilityIdentifier(identifier)
585	    } else {
586	      content
587	    }
588	  }
589	}
590	
591	/// A compact section-header action button matching the sidebar row-button convention: an SF
592	/// Symbol with a subtle rounded hover fill. `destructive` tints red on hover (like the row
593	/// delete button); neutral uses a faint primary fill (like the new-workroom button).
594	struct InspectorHeaderButton: View {
595	  let systemImage: String
596	  let help: String
597	  var destructive: Bool = false
598	  var disabled: Bool = false
599	  let action: () -> Void
600	  @State private var hovering = false
601	  private let theme = ThemeService.shared
602	
603	  var body: some View {
604	    Button(action: action) {
605	      Image(systemName: systemImage)
606	        .font(.system(size: 11))
607	        .foregroundStyle(destructive && hovering ? Color.red : theme.tokens.fgMuted)
608	        .inspectorHeaderButtonChrome(hovering: hovering, destructive: destructive)
609	    }
610	    .buttonStyle(.plain)
611	    .onHover { hovering = $0 }
612	    .help(help)
613	    .accessibilityLabel(help)
614	    .disabled(disabled)
615	  }
616	}
617	
618	extension View {
619	  /// Shared chrome for the inspector's three section-header icon buttons — Changes' Refresh,
620	  /// Notifications' Clear (both `InspectorHeaderButton`), and Pull Request's actions menu
621	  /// (`InspectorMenuButtonStyle`). A **fixed** hover-fill size (not glyph + padding) keeps the fill
622	  /// identical across the differently-shaped glyphs (the wide ellipsis vs. the narrow refresh/trash),
623	  /// centred in a larger **fixed** click target so all three match exactly. `contentShape` makes the
624	  /// whole target clickable/hoverable, not just the glyph.
625	  fileprivate func inspectorHeaderButtonChrome(hovering: Bool, destructive: Bool = false)
626	    -> some View
627	  {
628	    self
629	      .frame(width: 22, height: 22)
630	      .background(
631	        RoundedRectangle(cornerRadius: 5)
632	          .fill(
633	            (destructive ? Color.red : ThemeService.shared.tokens.hover)
634	              .opacity(hovering ? (destructive ? 0.18 : 1) : 0))
635	      )
636	      .frame(width: 28, height: 26)
637	      .contentShape(Rectangle())
638	  }
639	}
640	
641	/// Button style for the Pull Request header's actions `Menu`, used via `.menuStyle(.button)` so the
642	/// trigger is a SwiftUI button (a `.borderlessButton` menu is AppKit-backed and never reports
643	/// hover). It mirrors `InspectorHeaderButton`: a centred glyph, the same rounded hover fill, and the
644	/// same comfortable click target so all three header buttons match.
645	private struct InspectorMenuButtonStyle: ButtonStyle {
646	  func makeBody(configuration: Configuration) -> some View {
647	    HoverFill(configuration: configuration)
648	  }
649	
650	  private struct HoverFill: View {
651	    let configuration: ButtonStyle.Configuration
652	    @State private var hovering = false
653	
654	    var body: some View {
655	      configuration.label
656	        .inspectorHeaderButtonChrome(hovering: hovering || configuration.isPressed)
657	        .onHover { hovering = $0 }
658	    }
659	  }
660	}
661	
662	/// The Changes section body: the selected workroom's branch, sync state, working-tree changes
663	/// (relative to HEAD), and CI. Reads `store.selectedTargetID` + `store.workroomStatuses`.
664	/// Covers the empty/edge states the design review enumerated: nothing selected, a project
665	/// (non-target), missing directory, still-loading, unknown (probe failed), and clean.
666	struct ChangesPanel: View {
667	  @EnvironmentObject var store: AppStore
668	  private let theme = ThemeService.shared
669	  /// Hard cap on rendered rows so a huge change set can't blow up the list (the underlying
670	  /// output is already byte-capped by `StatusCommandRunner`).
671	  private let renderCap = 200
672	
673	  var body: some View {
674	    Group {
675	      if let sid = store.inspectorTargetID, sid.isStatusable {
676	        content(for: sid)
677	      } else {
678	        inspectorMessage("Select a workroom to see its changes.")
679	      }
680	    }
681	    .frame(maxWidth: .infinity, alignment: .leading)
682	  }
683	
684	  @ViewBuilder
685	  private func content(for sid: SidebarID) -> some View {
686	    let target = store.target(for: sid)
687	    let status = store.workroomStatuses[sid]
688	    if let target, target.isMissing {
689	      inspectorMessage("Directory not found.")
690	    } else if status == nil || status?.lastChecked == nil {
691	      inspectorMessage("Checking\u{2026}")
692	    } else if let status {
693	      // The branch/bookmark name is NOT repeated here — the VCS toolbar above this section shows it,
694	      // through the same `AppStore.branchName(for:)` accessor this panel used to read, so the pill was
695	      // saying the same thing twice about 40pt apart. What's left is backend-shaped: git's working tree
696	      // carries no metadata of its own, so it renders as a bare change list, while jj's `@` IS a commit
697	      // and keeps its change-id/commit-id/refs + description header. `jjWorkingCopy != nil` is the
698	      // discriminator — a failed probe leaves it nil, so failures fall to the git path.
699	      if let workingCopy = status.jjWorkingCopy {
700	        jjContent(workingCopy: workingCopy, sid: sid)
701	      } else {
702	        gitContent(status: status)
703	      }
704	    }
705	  }
706	
707	  /// Git repos: just the working-tree change list (or clean/failure). No header — git's working tree
708	  /// isn't a commit, so with the branch name moved to the toolbar there is nothing left to head it with,
709	  /// and the divider went with it rather than ruling off an empty row. CI is GitHub-derived, so it lives
710	  /// in the Pull Request section — not here.
711	  @ViewBuilder
712	  private func gitContent(status: WorkroomStatus) -> some View {
713	    VStack(alignment: .leading, spacing: 10) {
714	      if let failure = status.failure {
715	        inspectorMessage(failureText(failure))
716	      } else if status.isClean {
717	        cleanState
718	      } else {
719	        fileList(status.changedFiles ?? [], source: .gitWorktree)
720	      }
721	    }
722	    .padding(12)
723	  }
724	
725	  /// jj repos: the working copy (`@`) — because `@` is itself a commit, its change-id/commit-id/refs
726	  /// and description — over the flat change list. The working copy's parent (`@-`) is no longer shown
727	  /// here; the History panel now surfaces it.
728	  @ViewBuilder
729	  private func jjContent(workingCopy: JJCommitChanges, sid: SidebarID) -> some View {
730	    VStack(alignment: .leading, spacing: 10) {
731	      changesHeader(meta: workingCopy, identifier: "changes.workingCopy", sid: sid)
732	      Divider()
733	      if workingCopy.files.isEmpty {
734	        cleanState
735	      } else {
736	        fileList(workingCopy.files, source: .jjWorkingCopy)
737	      }
738	    }
739	    .padding(12)
740	  }
741	
742	  /// The jj working copy's header: `@`'s change-id (purple) / commit-id (blue) / its bookmarks, and the
743	  /// description line. **jj only** — git's working tree isn't a commit, so it carries no refs and no
744	  /// message and now renders headerless. `identifier` combines this into one a11y element; it is also
745	  /// the panel's render sentinel, which a dozen UI tests wait on before asserting anything else.
746	  /// The refs worth chipping: every bookmark on `@` EXCEPT the one the toolbar's bookmark segment is
747	  /// already showing, which is the only one most workrooms have.
748	  ///
749	  /// Filtered against `branchName(for:)` — the same accessor the toolbar reads — rather than against
750	  /// `meta.refs.first`, so the two can't disagree about which chip is the redundant one. A commit can
751	  /// carry several bookmarks and the toolbar names exactly one, so the rest still chip here; this
752	  /// removes a duplicate, not the information.
753	  private func extraRefs(_ meta: JJCommitChanges, sid: SidebarID) -> [String] {
754	    guard let shown = store.branchName(for: sid) else { return meta.refs }
755	    return meta.refs.filter { $0 != shown }
756	  }
757	
758	  @ViewBuilder
759	  private func changesHeader(meta: JJCommitChanges, identifier: String?, sid: SidebarID)
760	    -> some View
761	  {
762	    VStack(alignment: .leading, spacing: 2) {
763	      HStack(alignment: .firstTextBaseline, spacing: 6) {
764	        if let changeID = meta.changeID {
765	          Text(changeID).font(.system(.callout, design: .monospaced))
766	            .foregroundStyle(.purple).help("Change ID")
767	        }
768	        if let commitID = meta.commitID {
769	          Text(commitID).font(.system(.callout, design: .monospaced))
770	            .foregroundStyle(.blue).help("Commit ID")
771	        }
772	        // The bookmark the toolbar shows does NOT chip here — see `extraRefs`. jj reports a bookmarked
773	        // `@`'s name twice (as the status' `branchForCI` and again in `refs`), so this row has always
774	        // needed a filter to avoid one bookmark reading as two capsules; what changed is the reference
775	        // point. It used to be the branch-name pill that stood to the left of these chips. That pill is
776	        // gone, and for one commit in between so was the filter — which put the bookmark back on screen
777	        // twice, ~40pt below the toolbar segment that names it. Now it's the toolbar's own answer.
778	        //
779	        // The same gray capsules the History list rows and changeset header use, one step down from
780	        // the ids beside them (`.caption` under `.callout`, as the list's `.caption2` sits under its
781	        // `.caption`) so a pill doesn't outweigh this header's larger type.
782	        ForEach(extraRefs(meta, sid: sid), id: \.self) { ref in
783	          Text(ref).font(.caption)
784	            .lineLimit(1).truncationMode(.tail)
785	            .padding(.horizontal, 5).padding(.vertical, 1)
786	            .background(.quaternary, in: Capsule())
787	            .help("Bookmark / branch")
788	        }
789	        Spacer(minLength: 0)
790	      }
791	      if let desc = meta.description {
792	        Text(desc).font(.callout).foregroundStyle(.primary)
793	          .lineLimit(1).truncationMode(.tail)
794	      } else {
795	        Text("(no description set)").font(.footnote).foregroundStyle(.tertiary).lineLimit(1)
796	      }
797	    }
798	    .frame(maxWidth: .infinity, alignment: .leading)
799	    .modifier(CombinedA11y(identifier: identifier))
800	  }
801	
802	  /// The clean (no working-tree changes) state, styled like the Notifications empty state (issue
803	  /// #24 feedback): a small, dim, icon-first line rather than a full-size centered message.
804	  private var cleanState: some View {
805	    HStack(spacing: 6) {
806	      Image(systemName: "checkmark.circle").font(.callout).foregroundStyle(.tertiary)
807	      Text("No uncommitted changes").font(.callout).foregroundStyle(.secondary)
808	      Spacer(minLength: 0)
809	    }
810	    .frame(maxWidth: .infinity, alignment: .leading)
811	    .accessibilityElement(children: .ignore)
812	    .accessibilityLabel("No uncommitted changes")
813	  }
814	
815	  @ViewBuilder
816	  private func fileList(_ files: [ChangedFile], source: DiffSource) -> some View {
817	    let shown = Array(files.prefix(renderCap))
818	    VStack(alignment: .leading, spacing: 1) {
819	      ForEach(shown) { file in
820	        ChangedFileRow(file: file, source: source, sessions: store.terminals)
821	      }
822	      if files.count > shown.count {
823	        Text("Showing first \(shown.count) of \(files.count)")
824	          .font(.footnote).foregroundStyle(.tertiary)
825	      }
826	    }
827	  }
828	
829	  /// Split a repo-relative path into (directory, filename). A root-level file → empty directory.
830	  static func splitPath(_ path: String) -> (dir: String, name: String) {
831	    guard let slash = path.lastIndex(of: "/") else { return ("", path) }
832	    return (String(path[..<slash]), String(path[path.index(after: slash)...]))
833	  }
834	
835	  private func failureText(_ f: VCSStatusFailure) -> String {
836	    switch f {
837	    case .missingPath: return "Directory not found."
838	    case .notRepository: return "Not a repository."
839	    case .timeout: return "Status unavailable (timed out)."
840	    case .busy: return "Repository is busy — another VCS command is running."
841	    case .staleWorkingCopy: return "Working copy is out of date. Run `jj workspace update-stale`."
842	    }
843	  }
844	}
845	
846	extension SidebarID {
847	  /// A row whose VCS status the inspector can show: the project root or a workroom, but not the
848	  /// collapsed `.project` group header. Shared by the Changes and Pull Request panels.
849	  var isStatusable: Bool {
850	    if case .project = self { return false }
851	    return true
852	  }
853	}
854	
855	/// The inspector's "nothing to show" placeholder line (e.g. "Select a workroom…"), shared by the
856	/// Changes and Pull Request panels so they read identically.
857	func inspectorMessage(_ text: String) -> some View {
858	  Text(text)
859	    .font(.body)
860	    .foregroundStyle(.secondary)
861	    .frame(maxWidth: .infinity, alignment: .leading)
862	    .padding(12)
863	}
